import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import {
  getInstancePage,
  createInstancePage,
  updateInstancePage,
  buildInstancePage,
  executePageAction,
  listInstances,
  type InstancePageAction,
} from '@/shared/api/admin';
import type { Instance } from '@/features/instances/types/instance';
import type {
  InstancePage,
  CreateInstancePagePayload,
  UpdateInstancePagePayload,
} from '@/shared/types/instancePage';
import { parseSubPages, parsePageComponents, parsePageConfigure } from '@/shared/types/instancePage';
import { parseConfig } from '@/shared/hooks/useInstance';
import FormPage from '@/shared/components/forms/FormPage';
import { PILL_TAB_STYLE } from '@/shared/components/ui/PageActionsPill';
import PageFormActionsPill from '@/shared/components/ui/PageFormActionsPill';
import PillHistoryControls from '@/shared/components/ui/PillHistoryControls';
import { useFormHistory } from '@/shared/hooks/useFormHistory';
import FormSkeleton from '@/shared/components/ui/FormSkeleton';
import type { PageContent } from '@/shared/components/ui/CustomPageView';
import type { PageStudioTabId } from '@/features/instance-pages/types/pageStudio';
import { sectionCls } from '@/features/instance-pages/types/pageStudio';
import type { ActionRow, SubPageRow, ComponentRow, ConfigureRow } from '@/features/instance-pages/types/pageStudio';
import type { PageStarter } from '@/features/instance-pages/templates/pageStarters';
import { PAGE_STARTERS } from '@/features/instance-pages/templates/pageStarters';
import {
  getErrorMessage,
  blankAction,
  actionsToDefs,
  defsToActions,
  blankSub,
  subRowsFromJSON,
  subsToJSON,
  validateSubRows,
  blankComponent,
  compRowsFromJSON,
  compsToJSON,
  validateCompRows,
  blankConfigure,
  configureRowsFromJSON,
  configureToJSON,
  validateConfigureRows,
  validateActionRows,
} from '@/features/instance-pages/utils/pageStudioUtils';
import {
  PageStudioTabs,
  PageStudioTemplatesSection,
  PageStudioContentSection,
  PageStudioReactSection,
  PageStudioSubPagesSection,
  PageStudioActionsSection,
  PageStudioComponentsSection,
  PageStudioConfigureSection,
  PageStudioPreviewSection,
  PageStudioSettingsSection,
} from '@/features/instance-pages/components/PageStudio';

// ---------------------------------------------------------------------------
// Main Studio component — mirrors panel/frontend/src/features/templates/pages/TemplateForm.tsx
//
// Layout:
//   FormPage
//     grid [220px tabs | form body]
//       PageStudioTabs (left rail, sticky)
//       per-tab Section components (right, one visible at a time)
//
// Each Section lives under components/PageStudio/* so this file stays thin
// like TemplateForm.tsx — only state + wiring, no inline tab markup.
// Comments use the same "Section X · ..." headings as TemplateForm's
// Template*Section components.
// ---------------------------------------------------------------------------

const InstancePageStudio: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams<{ id?: string }>();
  const isEdit = Boolean(id);
  const pageId = id ? Number(id) : null;

  const [activeTab, setActiveTab] = useState<PageStudioTabId>('editor');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [executingAction, setExecutingAction] = useState<string | null>(null);
  // Test-execute output, keyed to the row that produced it so the result only
  // renders inside that action's card.
  const [actionResult, setActionResult] = useState<{ id: string; stdout: string; stderr: string; exit_code: number } | null>(null);

  // Page metadata + content
  const [page, setPage] = useState<Partial<InstancePage>>({
    name: '',
    description: '',
    slug: '',
    kind: 'custom' as InstancePage['kind'],
    category: '',
    type: '',
    content_type: 'html',
    content_html: '',
    content_markdown: '',
    content_blocks: '',
    source_tsx: '',
    bundle_css: '',
    icon_svg: '',
    icon_color: '',
    actions: '',
  });
  // React build state (POST /:id/build result surfaced on the React tab).
  const [building, setBuilding] = useState(false);

  // Saved-action rows (edited on the Actions tab, persisted with the page).
  const [actions, setActions] = useState<ActionRow[]>([]);

  // Component rows (edited on the Components tab)
  const [components, setComponents] = useState<ComponentRow[]>([]);

  // Configure rows (edited on the Configure tab) — page-level env vars (like template env)
  const [configure, setConfigure] = useState<ConfigureRow[]>([]);

  // Sub-page rows (edited on the Sub-pages tab) — extra routes that ship
  // with this page (multi-page support, e.g. files/edit).
  const [subs, setSubs] = useState<SubPageRow[]>([]);
  const [editingSubId, setEditingSubId] = useState<string | null>(null);
  // Preview target: 'main' or a sub-page row id.
  const [previewTarget, setPreviewTarget] = useState<string>('main');

  // Full-screen preview: keeps the panel shell (header + sidebar) visible and
  // hides every other piece of studio chrome. The overlay is measured over
  // the app's <main> region so header and sidebar are never covered.
  const [fullPreview, setFullPreview] = useState(false);
  const [mainRect, setMainRect] = useState<{ top: number; left: number; width: number; height: number } | null>(null);
  useEffect(() => {
    if (!fullPreview) return;
    const measure = () => {
      const main = document.querySelector('main');
      if (!main) { setMainRect(null); return; }
      const r = main.getBoundingClientRect();
      setMainRect({ top: r.top, left: r.left, width: r.width, height: r.height });
    };
    measure();
    window.addEventListener('resize', measure);
    return () => window.removeEventListener('resize', measure);
  }, [fullPreview]);
  useEffect(() => {
    if (!fullPreview) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') setFullPreview(false); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [fullPreview]);
  // Leaving the Preview tab always drops out of full screen so chrome returns.
  useEffect(() => {
    if (activeTab !== 'preview' && fullPreview) setFullPreview(false);
  }, [activeTab, fullPreview]);

  // Blocks visual editor state
  const [blocksMode, setBlocksMode] = useState<'visual' | 'json'>('visual');

  // Starter gallery search (Templates tab).
  const [templateSearch, setTemplateSearch] = useState('');

  // Preview / test target
  const [instances, setInstances] = useState<Instance[]>([]);
  const [previewInstanceId, setPreviewInstanceId] = useState<number | null>(null);
  const [refreshing, setRefreshing] = useState(false);

  const isBuiltin = page.kind === 'builtin';

  // Session edit history over the page document + row collections
  // (preview/test UI, build output flags stay out — build results land in
  // `page` via handleBuild and are harmlessly captured as ordinary edits).
  const snapshot = JSON.stringify({ page, actions, components, configure, subs });
  const hist = useFormHistory(snapshot, (snapStr) => {
    const s = JSON.parse(snapStr);
    setPage(s.page);
    setActions(s.actions);
    setComponents(s.components);
    setConfigure(s.configure);
    setSubs(s.subs);
  });
  const { suspend: histSuspend } = hist;

  // Load page (edit mode) + instances for preview/test.
  const load = useCallback(async () => {
    histSuspend();
    setError('');
    try {
      const list = await listInstances();
      setInstances(list);
    } catch {
      // preview picker just stays empty
    }
    if (!isEdit || pageId == null) {
      setLoading(false);
      return;
    }
    try {
      const found = await getInstancePage(pageId);
      setPage({ ...found });
      setActions(defsToActions(found.actions));
      setSubs(subRowsFromJSON(found.sub_pages));
      setComponents(compRowsFromJSON(found.components));
      setConfigure(configureRowsFromJSON((found as any).configure));
    } catch (e: any) {
      setError(getErrorMessage(e, 'Failed to load page'));
    } finally {
      setLoading(false);
    }
  }, [pageId, isEdit, histSuspend]);

  useEffect(() => {
    void load();
  }, [load]);

  // Refresh reloads saved values from the server in edit mode; in create
  // mode it reverts to the blank page.
  const refresh = async () => {
    if (refreshing) return;
    if (!isEdit) {
      hist.revert();
      return;
    }
    setRefreshing(true);
    try {
      await load();
    } finally {
      setRefreshing(false);
    }
  };

  useEffect(() => {
    if (!isEdit) setLoading(false);
  }, [isEdit]);

  const currentContent = useMemo(() => {
    if (page.content_type === 'html') return page.content_html ?? '';
    if (page.content_type === 'markdown') return page.content_markdown ?? '';
    if (page.content_type === 'react') return (page as any).source_tsx ?? '';
    return page.content_blocks ?? '';
  }, [page.content_type, page.content_html, page.content_markdown, page.content_blocks, (page as any).source_tsx]);

  const actionDefs = useMemo(() => actionsToDefs(actions), [actions]);

  const onChange = <K extends keyof InstancePage>(key: K, value: InstancePage[K]) => {
    setPage((p) => ({ ...p, [key]: value }));
    if (key === 'name' || key === 'slug') setError('');
  };

  useEffect(() => {
    if (error && page.name?.trim() && page.slug?.trim()) {
      setError('');
    }
  }, [page.name, page.slug]);

  const handleContentChange = (value: string) => {
    if (page.content_type === 'html') onChange('content_html', value);
    else if (page.content_type === 'markdown') onChange('content_markdown', value);
    else if ((page.content_type as string) === 'react') onChange('source_tsx' as any, value as any);
    else onChange('content_blocks', value);
  };

  // Build the React bundle (validates Studio source server-side). The build
  // endpoint validates sub-pages from STORED sub_pages, so the draft (main
  // source + sub rows) is persisted first — otherwise Build would validate
  // stale subs and report ok on outdated sources.
  const draftPayload = () => {
    const iconColor = ((page as any).icon_color || '').trim();
    return {
      name: page.name!.trim(),
      description: page.description ?? '',
      slug: page.slug!.trim(),
      kind: page.kind ?? 'custom',
      category: page.category ?? '',
      type: page.type ?? '',
      content_type: page.content_type || 'html',
      content_html: page.content_html ?? '',
      content_markdown: page.content_markdown ?? '',
      content_blocks: page.content_blocks ?? '',
      source_tsx: (page as any).source_tsx ?? '',
      bundle_css: (page as any).bundle_css ?? '',
      icon_svg: page.icon_svg ?? '',
      icon_color: iconColor.toUpperCase(),
      actions: JSON.stringify(actionDefs),
      sub_pages: subsToJSON(subs),
      components: compsToJSON(components),
      configure: configureToJSON(configure),
    } as unknown as UpdateInstancePagePayload;
  };

  const handleBuild = async () => {
    if (!isEdit || pageId == null) { setError('Save the page first to build it.'); return; }
    const subErr = validateSubRows(subs);
    if (subErr) { setError(subErr); return; }
    // Build persists the draft first, so action rows must validate here too
    // (same gate as handleSave) instead of failing inside the pre-save.
    const buildActionErr = validateActionRows(actions);
    if (buildActionErr) { setError(buildActionErr); return; }
    if ((page.content_type as string) === 'react' && !((page as any).source_tsx ?? '').trim()) {
      setError('React pages need source before building (React tab → Starter).');
      return;
    }
    setBuilding(true);
    setError('');
    try {
      // Persist the draft first so the family build validates current sources.
      await updateInstancePage(pageId, draftPayload());
      const res = await buildInstancePage(pageId, {
        source_tsx: (page as any).source_tsx ?? '',
        bundle_css: (page as any).bundle_css ?? '',
      });
      setPage((p) => ({ ...p, build_status: res.build_status, build_log: res.build_log } as any));
      if (res.build_status === 'ok') {
        // Mirror the server stamp (sub bundle_js = sub source_tsx) so the
        // draft rows stay consistent without refetching over unsaved tabs.
        setSubs((prev) => prev.map((s) =>
          (s.content_type as string) === 'react' && s.source_tsx.trim() ? { ...s, bundle_js: s.source_tsx } : s,
        ));
      }
      setNotice(res.build_status === 'ok' ? 'Build ok — bundle stored. Re-link templates to ship it.' : `Build: ${res.build_log}`);
    } catch (e: any) {
      setPage((p) => ({ ...p, build_status: 'error' } as any));
      setError(getErrorMessage(e, 'Build failed'));
    } finally {
      setBuilding(false);
    }
  };

  // ---- Starter gallery --------------------------------------------------
  // Applies a PageStarter into the draft. Meta (name/slug/…) is only filled
  // on create so applying a template while editing never breaks linked
  // slugs; content + actions + sub-pages always apply (explicit user action).
  const filteredStarters = useMemo(() => {
    const q = templateSearch.trim().toLowerCase();
    if (!q) return PAGE_STARTERS;
    return PAGE_STARTERS.filter((s) =>
      s.name.toLowerCase().includes(q) ||
      s.slug.toLowerCase().includes(q) ||
      s.category.toLowerCase().includes(q) ||
      s.description.toLowerCase().includes(q),
    );
  }, [templateSearch]);

  const applyStarter = (s: PageStarter) => {
    const st = s.contentType ?? (s.blocks ? 'blocks' : s.markdown ? 'markdown' : 'html');
    setPage((p) => ({
      ...p,
      // Meta only on create — editing keeps the stable slug linked templates use.
      ...(!isEdit ? { name: s.name, slug: s.slug, category: s.category, description: s.description, icon_svg: s.iconSvg } : {}),
      content_type: st,
      content_html: st === 'html' ? (s.html ?? '') : p.content_html,
      content_markdown: st === 'markdown' ? (s.markdown ?? '') : p.content_markdown,
      content_blocks: st === 'blocks' ? (s.blocks ?? '') : p.content_blocks,
    }));
    setBlocksMode('visual');
    if (Array.isArray(s.actions)) setActions(defsToActions(JSON.stringify(s.actions)));
    if (Array.isArray(s.subPages)) {
      const rows = subRowsFromJSON(JSON.stringify(s.subPages));
      setSubs(rows);
      setEditingSubId(null);
      if (previewTarget !== 'main') setPreviewTarget('main');
    }
    setError('');
    setNotice(`Template "${s.name}" applied — review and save.`);
    setActiveTab('editor');
  };

  const addAction = () => setActions((a) => [...a, blankAction()]);
  const removeAction = (actionId: string) => {
    setActions((a) => a.filter((x) => x.id !== actionId));
  };
  const updateAction = (actionId: string, patch: Partial<ActionRow>) => {
    setActions((a) => a.map((x) => (x.id === actionId ? { ...x, ...patch } : x)));
  };

  // ---- Component row handlers ---------------------------------------------
  const addComponent = () => setComponents((c) => [...c, blankComponent()]);
  const removeComponent = (id: string) => setComponents((c) => c.filter((x) => x.id !== id));
  const updateComponent = (id: string, patch: Partial<ComponentRow>) => setComponents((c) => c.map((x) => (x.id === id ? { ...x, ...patch } : x)));
  // Virtual modules (Files): components rows with type 'module' ({name,
  // content}) inlined by `import './name'` at transpile time. The React tab
  // owns them; preview/link carry them via the payload's components.
  const moduleFiles = useMemo(
    () => components.filter((c) => c.type === 'module').map((c) => ({ name: c.name, content: c.content })),
    [components],
  );
  const updateModuleFiles = (mods: Array<{ name: string; content: string }>) => {
    setComponents((prev) => {
      const rest = prev.filter((c) => c.type !== 'module');
      const byName = new Map(prev.filter((c) => c.type === 'module').map((c) => [c.name, c]));
      const rows: ComponentRow[] = mods.map((m) => {
        const existing = byName.get(m.name);
        if (existing) return { ...existing, content: m.content };
        return {
          id: `c${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          name: m.name,
          type: 'module' as const,
          description: '',
          content: m.content,
        };
      });
      return [...rest, ...rows];
    });
    // Modules ship inside the bundle — a Files edit invalidates the stored
    // build like a source edit does.
    setPage((p) => ({ ...p, build_status: '', build_log: '' } as any));
  };
  // Import a panel-shared component by reference (stores name only — the
  // panel supplies the source at render time). Duplicate names are ignored
  // so {{component:name}} tokens never become ambiguous.
  const importSharedComponent = (s: { name: string; label: string; description: string }) => {
    const key = (s.name || '').trim();
    if (!key) return;
    // Duplicate check runs on render-scope state (fresh every render) so the
    // updater below stays pure — side effects inside updaters double-fire
    // under StrictMode.
    if (components.some((x) => (x.name || '').trim() === key || ((x.shared || '').trim() === key && x.type === 'shared'))) {
      setNotice(`"${key}" is already in Components.`);
      return;
    }
    const row: ComponentRow = {
      id: `c${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      name: key,
      type: 'shared',
      description: s.description || `Panel shared: ${s.label || key}`,
      content: '',
      shared: key,
      editable: false,
    };
    setNotice(`Imported "${key}" — use {{component:${key}}} in content.`);
    setComponents((prev) => {
      if (prev.some((x) => (x.name || '').trim() === key)) return prev;
      return [...prev, row];
    });
  };

  // ---- Configure row handlers ---------------------------------------------
  const addConfigure = () => setConfigure((c) => [...c, blankConfigure()]);
  const removeConfigure = (id: string) => setConfigure((c) => c.filter((x) => x.id !== id));
  const updateConfigure = (id: string, patch: Partial<ConfigureRow>) => setConfigure((c) => c.map((x) => (x.id === id ? { ...x, ...patch } : x)));
  const moveConfigure = (id: string, dir: -1 | 1) => {
    setConfigure((prev) => {
      const idx = prev.findIndex((x) => x.id === id);
      if (idx < 0) return prev;
      const j = idx + dir;
      if (j < 0 || j >= prev.length) return prev;
      const next = [...prev];
      [next[idx], next[j]] = [next[j], next[idx]];
      return next;
    });
  };

  // ---- Sub-page row handlers ----------------------------------------------
  const addSub = () => {
    const row = blankSub();
    setSubs((s) => [...s, row]);
    setEditingSubId(row.id);
  };
  const updateSub = (subId: string, patch: Partial<SubPageRow>) => {
    setSubs((s) => s.map((x) => (x.id === subId ? { ...x, ...patch } : x)));
  };
  const removeSub = (subId: string) => {
    setSubs((s) => s.filter((x) => x.id !== subId));
    if (editingSubId === subId) setEditingSubId(null);
    if (previewTarget === subId) setPreviewTarget('main');
  };
  const moveSub = (idx: number, dir: -1 | 1) => {
    setSubs((s) => {
      const j = idx + dir;
      if (j < 0 || j >= s.length) return s;
      const next = [...s];
      [next[idx], next[j]] = [next[j], next[idx]];
      return next;
    });
  };

  const previewInstance = useMemo(
    () => instances.find((i) => i.id === previewInstanceId) ?? null,
    [instances, previewInstanceId],
  );

  const previewContext = useMemo(() => {
    if (!previewInstance) return null;
    return {
      id: previewInstance.id,
      name: previewInstance.name,
      kind: previewInstance.kind,
      status: previewInstance.status,
      template_id: previewInstance.template_id,
      template_name: previewInstance.template_name ?? null,
      node_id: previewInstance.node_id,
      node_name: previewInstance.node_name ?? null,
      owner_id: previewInstance.owner_id ?? null,
      owner_name: previewInstance.owner_name ?? null,
      config: previewInstance.config ? parseConfig(previewInstance.config) : {},
      external_id: previewInstance.external_id ?? '',
      created_at: previewInstance.created_at ?? '',
      updated_at: previewInstance.updated_at ?? '',
    };
  }, [previewInstance]);

  // Preview renders the main page or the selected sub-page (multi-page).
  const editingSub = useMemo(() => subs.find((s) => s.id === previewTarget) ?? null, [subs, previewTarget]);

  const compDefs = useMemo(() => parsePageComponents(compsToJSON(components)), [components]);

  // Configure defs + default values for preview: the Studio has no
  // per-template values yet, so {{config:NAME}} resolves against defaults —
  // the same substitution the live page gets (defaults overlaid by config).
  const cfgDefs = useMemo(() => parsePageConfigure(configureToJSON(configure)), [configure]);
  const cfgDefaults = useMemo(() => {
    const out: Record<string, string> = {};
    for (const v of cfgDefs) {
      if (v.name) out[v.name] = v.default ?? '';
    }
    return out;
  }, [cfgDefs]);

  const previewContent = useMemo<PageContent>(() => {
    const src = editingSub;
    if (src) {
      return {
        type: src.content_type as PageContent['type'],
        html: src.content_html,
        markdown: src.content_markdown,
        blocks: src.content_blocks,
        // React sub-preview prefers the built bundle (what the runtime
        // executes) and falls back to draft source so authors see state
        // without building first — same preference as the main page below.
        bundle: (src.content_type as string) === 'react' ? (src.bundle_js || src.source_tsx || undefined) : undefined,
        bundleCss: (src.content_type as string) === 'react' ? (src.bundle_css || undefined) : undefined,
        // Components are defined at the page family level (React-like reusable
        // blocks). They must load on both main and sub-pages, so sub-page
        // preview shares the parent's components and actions.
        actions: actionDefs.length ? actionDefs : undefined,
        components: compDefs.length ? compDefs : undefined,
        configure: cfgDefs.length ? (cfgDefs as any) : undefined,
        config: Object.keys(cfgDefaults).length ? cfgDefaults : undefined,
      };
    }
    return {
      type: (page.content_type || 'html') as PageContent['type'],
      html: page.content_html,
      markdown: page.content_markdown,
      blocks: page.content_blocks,
      // React preview executes the draft source (build output equals source
      // in v1) so authors see state without building first.
      bundle: (page.content_type as string) === 'react' ? ((page as any).bundle_js || (page as any).source_tsx) : undefined,
      bundleCss: (page.content_type as string) === 'react' ? ((page as any).bundle_css ?? '') : undefined,
      actions: actionDefs.length ? actionDefs : undefined,
      components: compDefs.length ? compDefs : undefined,
      configure: cfgDefs.length ? (cfgDefs as any) : undefined,
      config: Object.keys(cfgDefaults).length ? cfgDefaults : undefined,
    };
  }, [editingSub, page.content_type, page.content_html, page.content_markdown, page.content_blocks, (page as any).source_tsx, (page as any).bundle_js, (page as any).bundle_css, actionDefs, compDefs, cfgDefs, cfgDefaults]);

  // Test-execute a saved action against the selected instance. The backend
  // only runs it when this page's slug is enabled in that instance's spec.
  const testExecute = async (row: ActionRow) => {
    if (!pageId) { setError('Save the page first to test its actions.'); return; }
    if (!previewInstanceId) { setError('Pick a test instance (Actions or Preview tab) to test against.'); return; }
    const def = actionDefs.find((d) => d.name === row.name.trim());
    if (!def) { setError('The action needs a name before it can be tested.'); return; }
    setExecutingAction(row.id);
    setActionResult(null);
    setError('');
    try {
      const res = await executePageAction(pageId, previewInstanceId, def as InstancePageAction);
      setActionResult({ id: row.id, stdout: res.stdout ?? '', stderr: res.stderr ?? '', exit_code: res.exit_code ?? -1 });
    } catch (e: any) {
      setActionResult({ id: row.id, stdout: '', stderr: getErrorMessage(e, 'Action failed'), exit_code: -1 });
    } finally {
      setExecutingAction(null);
    }
  };

  const handleSave = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setError('');
    if (isBuiltin) { setError('Built-in pages cannot be edited. Create a custom page instead.'); return; }
    if (!page.name?.trim() || !page.slug?.trim()) { setError('Name and slug are required before saving.'); return; }
    // Length caps mirror validateInstancePage server-side
    // (instance_page_handler.go: maxInstancePageNameLen/maxInstancePageDescLen).
    if (page.name.trim().length > 200) { setError('Name too long (max 200 characters).'); return; }
    if ((page.description ?? '').length > 500) { setError('Description too long (max 500 characters).'); return; }
    if ((page.category ?? '').length > 500) { setError('Category too long (max 500 characters).'); return; }
    if ((page.type ?? '').length > 500) { setError('Type too long (max 500 characters).'); return; }
    if (page.slug.trim() !== '.' && !/^[a-z0-9][a-z0-9-._]*$/i.test(page.slug.trim())) { setError('Slug may contain letters, numbers, dots, dashes and underscores only ("." is the reserved Home slug).'); return; }
    if (page.slug?.trim().includes('..')) { setError('Slug must not contain ".." (path traversal).'); return; }
    if (page.slug && page.slug.trim().length > 64) { setError('Slug too long (max 64 characters).'); return; }
    const iconColor = ((page as any).icon_color || '').trim();
    if (iconColor && !/^#[0-9a-fA-F]{6}$/.test(iconColor)) { setError('Icon colour must be a #rrggbb hex value (or empty for default).'); return; }
    const subErr = validateSubRows(subs);
    if (subErr) { setError(subErr); return; }
    const compErr = validateCompRows(components);
    if (compErr) { setError(compErr); return; }
    const cfgErr = validateConfigureRows(configure);
    if (cfgErr) { setError(cfgErr); return; }
    const actionErr = validateActionRows(actions);
    if (actionErr) { setError(actionErr); return; }
    if ((page.content_type as string) === 'react' && !((page as any).source_tsx ?? '').trim()) {
      setError('React pages need source before saving (React tab → Starter).');
      return;
    }
    setSaving(true);
    setError('');
    try {
      const payload = draftPayload();
      if (isEdit && pageId != null) {
        await updateInstancePage(pageId, payload as UpdateInstancePagePayload);
      } else {
        await createInstancePage(payload as unknown as CreateInstancePagePayload);
      }
      hist.commit();
      navigate('/instance-pages');
    } catch (e: any) {
      setError(getErrorMessage(e, 'Save failed'));
    } finally {
      setSaving(false);
    }
  };

  // ---- Import / export ----------------------------------------------------
  const exportJson = () => {
    const data: Record<string, unknown> = {
      name: page.name ?? '',
      slug: page.slug ?? '',
      kind: page.kind ?? 'custom',
      category: page.category ?? '',
      type: page.type ?? '',
      description: page.description ?? '',
      content_type: page.content_type || 'html',
      content_html: page.content_html ?? '',
      content_markdown: page.content_markdown ?? '',
      content_blocks: page.content_blocks ?? '',
      source_tsx: (page as any).source_tsx ?? '',
      bundle_css: (page as any).bundle_css ?? '',
      icon_svg: page.icon_svg ?? '',
      icon_color: (page as any).icon_color ?? '',
      actions: actionDefs,
    };
    const subDefs = parseSubPages(subsToJSON(subs));
    if (subDefs.length > 0) data.pages = subDefs;
    const compDefs = parsePageComponents(compsToJSON(components));
    if (compDefs.length > 0) data.components = compDefs;
    const cfgDefs = parsePageConfigure(configureToJSON(configure));
    if (cfgDefs.length > 0) data.configure = cfgDefs;
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${page.slug || 'instance-page'}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const importFileRef = useRef<HTMLInputElement>(null);
  const importJson = async (file: File) => {
    try {
      const text = await file.text();
      const data = JSON.parse(text);
      if (!data || typeof data !== 'object') throw new Error('not an object');
      setPage((p) => ({
        ...p,
        name: typeof data.name === 'string' ? data.name : p.name,
        slug: typeof data.slug === 'string' ? data.slug : p.slug,
        // The legacy "builtin" kind is rejected by the API (migration 046);
        // imports coerce to custom so a stale JSON file can't brick the save.
        kind: 'custom' as InstancePage['kind'],
        category: typeof data.category === 'string' ? data.category : p.category,
        type: typeof data.type === 'string' ? data.type : p.type,
        description: typeof data.description === 'string' ? data.description : p.description,
        content_type: ['html', 'markdown', 'blocks', 'react'].includes(data.content_type) ? data.content_type : p.content_type,
        content_html: typeof data.content_html === 'string' ? data.content_html : p.content_html,
        content_markdown: typeof data.content_markdown === 'string' ? data.content_markdown : p.content_markdown,
        content_blocks: typeof data.content_blocks === 'string' ? data.content_blocks : p.content_blocks,
        source_tsx: typeof (data as any).source_tsx === 'string' ? (data as any).source_tsx : (p as any).source_tsx,
        bundle_css: typeof (data as any).bundle_css === 'string' ? (data as any).bundle_css : (p as any).bundle_css,
        icon_svg: typeof data.icon_svg === 'string' ? data.icon_svg : p.icon_svg,
        icon_color: typeof (data as any).icon_color === 'string' ? (data as any).icon_color : (p as any).icon_color,
        actions: Array.isArray(data.actions) ? JSON.stringify(data.actions) : p.actions,
      }));
      if (Array.isArray(data.actions)) setActions(defsToActions(JSON.stringify(data.actions)));
      // Library files (instance_pages/pages/*.yaml, GUIDE.md §2.1) store
      // sub-pages/components as native YAML lists; legacy *.json files store
      // them as JSON-encoded STRINGS; Studio exports use inline arrays.
      // Accept all three so every library file imports without dropping rows.
      if (Array.isArray(data.pages)) {
        const rows = subRowsFromJSON(JSON.stringify(data.pages));
        setSubs(rows);
        setEditingSubId(null);
      } else if (typeof data.sub_pages === 'string' && data.sub_pages.trim()) {
        setSubs(subRowsFromJSON(data.sub_pages));
        setEditingSubId(null);
      }
      if (Array.isArray(data.components)) {
        const rows = compRowsFromJSON(JSON.stringify(data.components));
        setComponents(rows);
      } else if (typeof data.components === 'string' && data.components.trim()) {
        setComponents(compRowsFromJSON(data.components));
      }
      if (Array.isArray((data as any).configure)) {
        const rows = configureRowsFromJSON(JSON.stringify((data as any).configure));
        setConfigure(rows);
      } else if (typeof (data as any).configure === 'string' && (data as any).configure.trim()) {
        setConfigure(configureRowsFromJSON((data as any).configure));
      }
      setNotice('Page JSON imported into the form. Review and save.');
    } catch (e: any) {
      setError(`Import failed: ${e?.message || e}`);
    }
  };

  if (loading) {
    return (
      <FormPage
        crumbs={[{ label: 'Instance Pages', to: '/instance-pages' }, { label: isEdit ? 'Edit Page' : 'New Page' }]}
        hideHeader
        maxWidth="max-w-4xl"
      >
        <FormSkeleton fields={6} />
      </FormPage>
    );
  }

  const contentType = (page.content_type || 'html') as 'html' | 'markdown' | 'blocks' | 'react';

  // Preview panel shared by the normal Preview tab and full-screen mode.
  // Delegated to PageStudioPreviewSection for consistency with template split.
  const previewSectionProps = {
    instances,
    previewInstanceId,
    onPreviewInstanceChange: setPreviewInstanceId,
    previewTarget,
    onPreviewTargetChange: setPreviewTarget,
    subs,
    pageName: page.name ?? '',
    pageSlug: page.slug ?? '',
    isBuiltin,
    isEdit,
    previewInstance,
    previewContext,
    previewContent,
    editingSub,
    contentType,
    currentContent,
    fullPreview,
    onToggleFullPreview: () => setFullPreview((v) => !v),
    sectionCls,
  };

  // Full-screen preview: only header + sidebar (the app shell around this
  // overlay) stay visible — every other studio element is not rendered.
  // Falls back to a full-viewport overlay when <main> is not measurable.
  if (fullPreview && activeTab === 'preview') {
    return (
      <div
        className="fixed z-40 overflow-hidden"
        style={mainRect ?? { top: 0, left: 0, right: 0, bottom: 0 }}
      >
        <PageStudioPreviewSection {...previewSectionProps} />
      </div>
    );
  }

  return (
    <>
      {/* Bottom-right form actions — undo / redo + Save;
          fixed, corner-anchored (right-4, w-auto) so the phone Tabs pill
          shares the same bottom line on the left instead of floating above
          with an empty gap underneath (ks-tabs-pill-wrap-below opts out of
          the global lift — instance-form pattern). */}
      <PageFormActionsPill
        spacer={false}
        outerClassName="fixed right-4 sm:right-6 bottom-[max(0.75rem,env(safe-area-inset-bottom))] z-40 flex justify-end w-auto max-w-[calc(100vw-2rem)]"
      >
          <PillHistoryControls hist={hist} />
          <button
            type="button"
            onClick={() => handleSave()}
            disabled={saving || isBuiltin}
            title={isEdit ? 'Save page' : 'Create page'}
            className="ks-tab ks-tab-active shrink-0 px-3 py-1.5 rounded text-sm text-center transition disabled:opacity-60"
            style={PILL_TAB_STYLE}
          >
            {saving ? 'Saving…' : isEdit ? 'Save' : 'Create'}
          </button>
      </PageFormActionsPill>
    <FormPage
      crumbs={[{ label: 'Instance Pages', to: '/instance-pages' }, { label: isEdit ? 'Edit Page' : 'New Page' }]}
      onSubmit={handleSave}
      maxWidth="max-w-4xl"
      hideHeader
      disabled={isBuiltin}
    >
      <div className="grid grid-cols-1 lg:grid-cols-[220px_minmax(0,1fr)] gap-4">
        {/* Phone tabs sit bottom-LEFT on the same bottom line as the Save/
            Create actions (bottom-right) — corner-anchored w-auto with
            ks-tabs-pill-wrap-below, so the global "lift above the form bar"
            rule never applies and no empty gap is left underneath
            (instance-form pattern). */}
        <PageStudioTabs
          tab={activeTab}
          onChange={setActiveTab}
          isBuiltin={isBuiltin}
          tabsPillOuterClassName="lg:hidden fixed left-4 bottom-[max(0.75rem,env(safe-area-inset-bottom))] z-30 flex justify-start w-auto max-w-[calc(100vw-2rem)] ks-tabs-pill-wrap-below"
        />

        <div className="space-y-4 min-w-0">
          {error && (
            <p className="text-red-400 flex items-start justify-between gap-2 border border-red-700/40 rounded px-3 py-2 bg-red-900/20">
              <span>{error}</span>
              <button type="button" onClick={() => setError('')} className="text-xs text-gray-400 hover:text-white">dismiss</button>
            </p>
          )}
          {notice && !error && (
            <p className="text-emerald-300 flex items-start justify-between gap-2 border border-emerald-700/40 rounded px-3 py-2 bg-emerald-900/20">
              <span>{notice}</span>
              <button type="button" onClick={() => setNotice('')} className="text-xs text-gray-400 hover:text-white">dismiss</button>
            </p>
          )}

          {isBuiltin && isEdit && (
            <div className="p-4 bg-amber-900/30 border border-amber-700/50 rounded-lg text-amber-200 text-sm">
              <p className="font-semibold">Built-in Page (Read-Only)</p>
              <p className="mt-1">
                Built-in pages are provided by the panel and cannot be edited here. To customize one for a
                specific template, use the <strong>Pages</strong> tab in the <strong>Template</strong> editor.
              </p>
            </div>
          )}

          {/* ============================== TEMPLATES ============================== */}
          {activeTab === 'templates' && !isBuiltin && (
            <PageStudioTemplatesSection
              search={templateSearch}
              onSearchChange={setTemplateSearch}
              starters={filteredStarters}
              query={templateSearch}
              onApply={applyStarter}
              sectionCls={sectionCls}
            />
          )}

          {/* ============================== CONTENT ============================== */}
          {activeTab === 'editor' && !isBuiltin && contentType !== 'react' && (
            <PageStudioContentSection
              contentType={contentType as 'html' | 'markdown' | 'blocks'}
              onContentTypeChange={(t) => { onChange('content_type', t); setBlocksMode('visual'); }}
              currentContent={currentContent}
              onContentChange={handleContentChange}
              contentBlocks={page.content_blocks ?? ''}
              onBlocksChange={(v) => {
                setPage((p) => ({ ...p, content_blocks: v }));
                if (page.content_type !== 'blocks') onChange('content_type', 'blocks');
              }}
              blocksMode={blocksMode}
              onBlocksModeChange={setBlocksMode}
              actionNames={actionDefs.map((d) => d.name)}
              onCopy={() => navigator.clipboard.writeText(currentContent)}
              onExport={exportJson}
              onImportClick={() => importFileRef.current?.click()}
              sectionCls={sectionCls}
            />
          )}

          {/* ============================== REACT ============================== */}
          {activeTab === 'editor' && !isBuiltin && contentType === 'react' && (
            <PageStudioReactSection
              source={(page as any).source_tsx ?? ''}
              // Editing the source invalidates the stored bundle (build-owned
              // columns): clear the status so the tab stops showing a stale
              // "Built ✓" until the next Build.
              onSourceChange={(v) => setPage((p) => ({ ...p, source_tsx: v, build_status: '', build_log: '' } as any))}
              css={(page as any).bundle_css ?? ''}
              onCssChange={(v) => setPage((p) => ({ ...p, bundle_css: v, build_status: '', build_log: '' } as any))}
              buildStatus={(page as any).build_status ?? ''}
              buildLog={(page as any).build_log ?? ''}
              onBuild={handleBuild}
              building={building}
              canBuild={isEdit && pageId != null}
              onContentTypeChange={(t) => { onChange('content_type', t); setBlocksMode('visual'); }}
              sectionCls={sectionCls}
              modules={moduleFiles}
              onModulesChange={updateModuleFiles}
            />
          )}

          {/* ============================== SUB-PAGES ============================== */}
          {activeTab === 'subpages' && !isBuiltin && (
            <PageStudioSubPagesSection
              subs={subs}
              editingSubId={editingSubId}
              onEditingChange={setEditingSubId}
              onAdd={addSub}
              onUpdate={updateSub}
              onRemove={removeSub}
              onMove={moveSub}
              pageSlug={page.slug}
              sectionCls={sectionCls}
            />
          )}

          {/* ============================== ACTIONS ============================== */}
          {activeTab === 'actions' && !isBuiltin && (
            <PageStudioActionsSection
              actions={actions}
              onAdd={addAction}
              onRemove={removeAction}
              onUpdate={updateAction}
              onTest={testExecute}
              pageId={pageId}
              previewInstanceId={previewInstanceId}
              onPreviewInstanceChange={setPreviewInstanceId}
              instances={instances}
              executingAction={executingAction}
              actionResult={actionResult}
              sectionCls={sectionCls}
            />
          )}

          {/* ============================== COMPONENTS ============================== */}
          {activeTab === 'components' && !isBuiltin && (
            <PageStudioComponentsSection
              components={components}
              onAdd={addComponent}
              onRemove={removeComponent}
              onUpdate={updateComponent}
              onImport={importSharedComponent}
              sectionCls={sectionCls}
            />
          )}

          {/* ============================== CONFIGURE ============================== */}
          {activeTab === 'configure' && !isBuiltin && (
            <PageStudioConfigureSection
              configure={configure}
              onAdd={addConfigure}
              onRemove={removeConfigure}
              onUpdate={updateConfigure}
              onMove={moveConfigure}
              sectionCls={sectionCls}
            />
          )}

          {/* ============================== PREVIEW ============================== */}
          {/* Built-ins render only the read-only note below — mounting the
              live preview as well would show two stacked preview sections. */}
          {activeTab === 'preview' && !isBuiltin && (
            <PageStudioPreviewSection {...previewSectionProps} />
          )}

          {/* ============================== SETTINGS ============================== */}
          {activeTab === 'settings' && !isBuiltin && (
            <PageStudioSettingsSection
              page={page}
              onChange={onChange}
              onExport={exportJson}
              onImportClick={() => importFileRef.current?.click()}
              sectionCls={sectionCls}
            />
          )}

          {/* Builtin read-only preview */}
          {activeTab === 'preview' && isBuiltin && (
            <div className={sectionCls}>
              <h4 className="text-sm font-semibold uppercase tracking-wide text-gray-400 mb-1">Section E · Preview (read-only)</h4>
              <p className="text-xs text-gray-500">Built-in pages render through their compiled components inside the instance panel; there is nothing to preview here.</p>
            </div>
          )}
          {activeTab !== 'preview' && isBuiltin && (
            <div className={sectionCls}>
              <p className="text-sm text-gray-400">This built-in page is read-only. Switch to Preview or manage it per-template in the Template editor&apos;s Pages tab.</p>
            </div>
          )}
        </div>
      </div>

      {/* Hidden file input for JSON import — triggered from Content + Settings */}
      <input
        ref={importFileRef}
        type="file"
        accept="application/json,.json"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files?.[0];
          if (f) importJson(f);
          e.target.value = '';
        }}
      />
    </FormPage>
      {/* Spacer — single bottom-pill row clearance (tabs left + Save/Create
          right share one line, instance-form pattern). */}
      <div aria-hidden="true" className="h-20 lg:hidden" />
    </>
  );
};

export default InstancePageStudio;
