// ---------------------------------------------------------------------------
// Error normalisation
// ---------------------------------------------------------------------------

// getErrorMessage normalises API failures for display: some panel endpoints
// answer with JSON bodies ({error|message}) instead of plain text, which would
// otherwise render as "[object Object]".
export function getErrorMessage(e: any, fallback: string): string {
  const data = e?.response?.data;
  if (typeof data === 'string' && data.trim()) return data;
  if (data && typeof data === 'object') {
    if (typeof data.error === 'string') return data.error;
    if (typeof data.message === 'string') return data.message;
    try { return JSON.stringify(data); } catch { return fallback; }
  }
  if (typeof e?.message === 'string' && e.message.trim()) return e.message;
  return fallback;
}

// ---------------------------------------------------------------------------
// Action rows — local editing shape <-> persisted PageActionDef JSON
// ---------------------------------------------------------------------------

let actionSeq = 0;
export function blankAction(): ActionRow {
  actionSeq += 1;
  return { id: `a${Date.now()}-${actionSeq}`, name: '', type: 'shell', command: '', path: '', content: '', args: '', open_args: false, env: '{}', timeout: '30', description: '', mode: '', names: '', dest: '' };
}

// actionsToDefs serialises editor rows into the persisted JSON shape.
// Rows without a name are dropped; invalid env JSON is dropped per-row so one
// bad row can't block saving the page.
export function actionsToDefs(rows: ActionRow[]): PageActionDef[] {
  const out: PageActionDef[] = [];
  for (const r of rows) {
    const name = r.name.trim();
    if (!name) continue;
    let env: Record<string, string> | undefined;
    if (r.env.trim() && r.env.trim() !== '{}') {
      try {
        const parsed = JSON.parse(r.env);
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
          env = Object.fromEntries(Object.entries(parsed).map(([k, v]) => [k, String(v)]));
        }
      } catch { /* skip invalid env */ }
    }
    out.push({
      name,
      type: r.type,
      command: r.command || undefined,
      path: r.path || undefined,
      content: r.content || undefined,
      args: r.args.trim() ? r.args.split(/\s+/).filter(Boolean) : undefined,
      ...(r.open_args ? { open_args: true } : {}),
      env,
      timeout: parseInt(r.timeout, 10) || undefined,
      description: r.description || undefined,
      mode: r.mode.trim() || undefined,
      names: r.names.trim() ? r.names.split(/\s+/).filter(Boolean) : undefined,
      dest: r.dest.trim() || undefined,
    });
  }
  return out;
}

export function defsToActions(json: string | undefined): ActionRow[] {
  let defs: any[] = [];
  if (json && json.trim()) {
    try {
      const parsed = JSON.parse(json);
      if (Array.isArray(parsed)) defs = parsed.filter((d) => d && typeof d === 'object');
    } catch { /* legacy/corrupt rows start fresh */ }
  }
  if (defs.length === 0) return [];
  return defs.map((d) => ({
    id: `d${actionSeq++}-${Math.random().toString(36).slice(2, 8)}`,
    name: typeof d.name === 'string' ? d.name : '',
    type: (['shell', 'read_file', 'write_file', 'list_files', 'docker', 'kvm', 'lxd', 'stat', 'chmod', 'archive', 'extract'].includes(d.type) ? d.type : 'shell') as ActionRow['type'],
    command: typeof d.command === 'string' ? d.command : '',
    path: typeof d.path === 'string' ? d.path : '',
    content: typeof d.content === 'string' ? d.content : '',
    args: Array.isArray(d.args) ? d.args.join(' ') : '',
    open_args: d.open_args === true,
    env: d.env && typeof d.env === 'object' ? JSON.stringify(d.env, null, 2) : '{}',
    timeout: d.timeout != null ? String(d.timeout) : '30',
    description: typeof d.description === 'string' ? d.description : '',
    mode: typeof d.mode === 'string' ? d.mode : '',
    names: Array.isArray(d.names) ? d.names.join(' ') : '',
    dest: typeof d.dest === 'string' ? d.dest : '',
  }));
}

// validateActionRows mirrors the backend's validatePageActions rules
// client-side (instance_page_handler.go:2536) so the operator gets a precise
// message before a round-trip. Rows without a name are dropped on save by
// actionsToDefs, so a half-filled unnamed row errors instead of vanishing.
export function validateActionRows(rows: ActionRow[]): string {
  const seen = new Set<string>();
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    const name = r.name.trim();
    const touched =
      name !== '' ||
      r.command.trim() !== '' ||
      r.path.trim() !== '' ||
      r.content.trim() !== '' ||
      r.args.trim() !== '' ||
      r.description.trim() !== '' ||
      r.mode.trim() !== '' ||
      r.names.trim() !== '' ||
      r.dest.trim() !== '';
    if (!touched) continue; // untouched row
    if (name === '') return `Action #${i + 1} needs a name before saving (unnamed actions are dropped).`;
    if (seen.has(name)) return `Duplicate action name "${name}".`;
    seen.add(name);
    if (!['shell', 'read_file', 'write_file', 'list_files', 'docker', 'kvm', 'lxd', 'stat', 'chmod', 'archive', 'extract'].includes(r.type)) {
      return `Action "${name}" has an unknown type "${r.type}".`;
    }
    if ((r.type === 'stat' || r.type === 'chmod' || r.type === 'archive') && r.path.trim() === '') {
      return `Action "${name}" (${r.type}) requires a path.`;
    }
    if (r.type === 'chmod') {
      const mode = r.mode.trim();
      if (!/^[0-7]{3,4}$/.test(mode) || parseInt(mode, 8) > 0o777) {
        return `Action "${name}" (chmod) requires mode 000-777.`;
      }
    }
    if (r.type === 'archive') {
      const dest = r.dest.trim().toLowerCase();
      if (!(dest.endsWith('.zip') || dest.endsWith('.tar.gz') || dest.endsWith('.tgz'))) {
        return `Action "${name}" (archive) requires dest ending with .zip or .tar.gz.`;
      }
    }
    if (r.type === 'extract') {
      const path = r.path.trim().toLowerCase();
      if (!(path.endsWith('.zip') || path.endsWith('.tar.gz') || path.endsWith('.tgz'))) {
        return `Action "${name}" (extract) requires path ending with .zip or .tar.gz.`;
      }
    }
  }
  return '';
}

// ---------------------------------------------------------------------------
// Sub-page rows — extra routes that ship with this page
// ---------------------------------------------------------------------------

let subSeq = 0;
export function blankSub(): SubPageRow {
  subSeq += 1;
  return { id: `s${Date.now()}-${subSeq}`, path: '', name: '', content_type: 'html', content_html: '', content_markdown: '', content_blocks: '', source_tsx: '', bundle_js: '', bundle_css: '' };
}

export function subRowsFromJSON(json: string | undefined | null): SubPageRow[] {
  const defs: InstancePageSubPage[] = parseSubPages(json);
  if (defs.length === 0) return [];
  return defs.map((d) => ({
    id: `p${subSeq++}-${Math.random().toString(36).slice(2, 8)}`,
    path: d.path,
    name: d.name,
    content_type: (['html', 'markdown', 'blocks', 'react'].includes(d.content_type) ? d.content_type : 'html') as SubPageRow['content_type'],
    content_html: typeof d.content_html === 'string' ? d.content_html : '',
    content_markdown: typeof d.content_markdown === 'string' ? d.content_markdown : '',
    content_blocks: typeof d.content_blocks === 'string' ? d.content_blocks : '',
    source_tsx: typeof (d as any).source_tsx === 'string' ? (d as any).source_tsx : '',
    // bundle_js is build-owned (stamped by POST /:id/build). It must survive
    // the load → edit → save round-trip or the next save wipes the deployed
    // bundle and React subs render "no built bundle".
    bundle_js: typeof (d as any).bundle_js === 'string' ? (d as any).bundle_js : '',
    bundle_css: typeof (d as any).bundle_css === 'string' ? (d as any).bundle_css : '',
  }));
}

// subsToJSON serialises editor rows into the persisted sub_pages shape.
// Fully blank rows are dropped; returns '' when nothing remains so the API
// stores "no sub-pages".
export function subsToJSON(rows: SubPageRow[]): string {
  const defs: InstancePageSubPage[] = rows
    .filter((r) => r.path.trim() !== '' || r.name.trim() !== '')
    .map((r) => ({
      path: r.path.trim(),
      name: r.name.trim(),
      content_type: r.content_type,
      content_html: r.content_html,
      content_markdown: r.content_markdown,
      content_blocks: r.content_blocks,
      ...(r.source_tsx ? { source_tsx: r.source_tsx } : {}),
      // Preserve the stamped sub bundle (build-owned). The backend's Update
      // overwrites sub_pages wholesale, so omitting this key here would wipe
      // a good build on the next plain save.
      ...(r.bundle_js ? { bundle_js: r.bundle_js } : {}),
      ...(r.bundle_css ? { bundle_css: r.bundle_css } : {}),
    }));
  if (defs.length === 0) return '';
  return JSON.stringify(defs);
}

// validateSubRows mirrors the backend's sub_pages rules client-side so the
// operator gets a precise message before a round-trip.
export function validateSubRows(rows: SubPageRow[]): string {
  // Blank rows are dropped on save (subsToJSON), so only count rows that
  // persist — same population the backend's max-sub-pages gate sees.
  const kept = rows.filter((r) => r.path.trim() !== '' || r.name.trim() !== '');
  if (kept.length > 20) return `Too many sub-pages (${kept.length}, max 20).`;
  const seen = new Set<string>();
  for (const r of rows) {
    const path = r.path.trim();
    const name = r.name.trim();
    if (path === '' && name === '') continue; // untouched row
    if (!/^[a-z0-9_-]+$/.test(path)) return `Sub-page path "${path || '(empty)'}" must be lowercase letters, numbers, dashes or underscores.`;
    if (name === '') return `Sub-page "/${path}" needs a display name.`;
    if (seen.has(path)) return `Duplicate sub-page path "/${path}".`;
    seen.add(path);
    if ((r.content_type as string) === 'react' && !r.source_tsx.trim()) {
      return `Sub-page "/${path}" needs React source before saving.`;
    }
  }
  return '';
}

// ---------------------------------------------------------------------------
// Component rows — reusable UI blocks ({name,type,description,content})
// ---------------------------------------------------------------------------

let compSeq = 0;
export function blankComponent(): ComponentRow {
  compSeq += 1;
  return { id: `c${Date.now()}-${compSeq}`, name: '', type: 'html', description: '', content: '', editable: true };
}

export function compRowsFromJSON(json: string | undefined | null): ComponentRow[] {
  const defs: PageComponentDef[] = parsePageComponents(json);
  if (defs.length === 0) return [];
  return defs.map((d) => {
    const rawEditable = (d as any).editable;
    const editable = typeof rawEditable === 'boolean' ? rawEditable : d.type === 'shared' ? false : true;
    return {
      id: `c${compSeq++}-${Math.random().toString(36).slice(2, 8)}`,
      name: d.name,
      type: (['html', 'markdown', 'block', 'shared', 'module'].includes(d.type) ? d.type : 'html') as ComponentRow['type'],
      description: d.description || '',
      content: d.content || '',
      editable,
      ...(d.type === 'shared' ? { shared: typeof (d as any).shared === 'string' && (d as any).shared ? (d as any).shared : d.name } : {}),
    };
  });
}

export function compsToJSON(rows: ComponentRow[]): string {
  const defs: PageComponentDef[] = rows
    .filter((r) => r.name.trim() !== '')
    .map((r) => {
      const editable = r.editable !== false;
      // Locked (editable === false): not editable, not saved whole in YAML — minimal shared ref always loads from panel.
      if (!editable) {
        const sharedKey = (r.shared || r.name).trim() || r.name.trim();
        return {
          name: r.name.trim(),
          type: 'shared' as const,
          description: r.description || '',
          content: '',
          shared: sharedKey,
          editable: false,
        } as PageComponentDef;
      }
      return {
        name: r.name.trim(),
        type: r.type,
        description: r.description,
        // Shared refs store no source — the panel supplies it at render time.
        content: r.type === 'shared' ? '' : r.content,
        ...(r.type === 'shared' ? { shared: (r.shared || r.name).trim() || r.name.trim() } : {}),
        editable: true,
      } as PageComponentDef;
    });
  if (defs.length === 0) return '';
  return JSON.stringify(defs);
}

export function validateCompRows(rows: ComponentRow[]): string {
  // Blank rows are dropped on save (compsToJSON), so only count rows that
  // persist — same population the backend's max-components gate sees.
  const kept = rows.filter((r) => r.name.trim() !== '');
  if (kept.length > 50) return `Too many components (${kept.length}, max 50).`;
  const seen = new Set<string>();
  let modules = 0;
  for (const r of rows) {
    const name = r.name.trim();
    if (name === '') continue; // untouched row
    if (!/^[A-Za-z0-9_][A-Za-z0-9_-]*$/.test(name)) return `Component name "${name}" must start with a letter, number or underscore and contain only letters, numbers, underscores or dashes.`;
    if (seen.has(name)) return `Duplicate component name "${name}".`;
    seen.add(name);
    if (r.type && !['html', 'markdown', 'block', 'shared', 'module'].includes(r.type)) return `Component "${name}" type must be one of: html, markdown, block, shared, module.`;
    if (r.type === 'module') modules += 1;
    if (r.type === 'shared') {
      const ref = (r.shared || r.name).trim();
      if (!/^[A-Za-z0-9_][A-Za-z0-9_-]*$/.test(ref)) return `Shared component "${name}" references an invalid panel component "${ref}".`;
    }
  }
  if (modules > 20) return `Too many modules (${modules}, max 20) — merge small helpers into fewer files.`;
  return '';
}

// ---------------------------------------------------------------------------
// Virtual modules — Files list backing (components type 'module')
// ---------------------------------------------------------------------------

// modulesFromRows extracts the transpile-time module table ({name: content})
// from editor rows. First name wins so a duplicate (blocked at save by
// validateCompRows) still bundles deterministically.
export function modulesFromRows(rows: ComponentRow[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (const r of rows) {
    if (r.type !== 'module') continue;
    const name = r.name.trim();
    if (!name || Object.prototype.hasOwnProperty.call(out, name)) continue;
    out[name] = r.content ?? '';
  }
  return out;
}

// modulesFromDefs is the same extraction for parsed PageComponentDef lists
// (preview/link payloads, which carry components verbatim).
export function modulesFromDefs(defs: PageComponentDef[] | undefined | null): Record<string, string> {
  const out: Record<string, string> = {};
  for (const d of defs ?? []) {
    if (!d || d.type !== 'module' || typeof d.name !== 'string' || !d.name) continue;
    if (Object.prototype.hasOwnProperty.call(out, d.name)) continue;
    out[d.name] = typeof d.content === 'string' ? d.content : '';
  }
  return out;
}

